<?php
/** Reusable sponsors, configurable tiers, and year-specific sponsorships. */
if (!defined('ABSPATH')) exit;
function caes_em_sponsors(){ $v=get_option('caes_em_sponsors',array());return is_array($v)?$v:array(); }
function caes_em_sponsor_tiers(){ $v=get_option('caes_em_sponsor_tiers',null);return is_array($v)?$v:array('presenting'=>array('name'=>'Presenting Sponsor','order'=>10,'active'=>1),'lead'=>array('name'=>'Lead Sponsor','order'=>20,'active'=>1),'supporting'=>array('name'=>'Supporting Sponsor','order'=>30,'active'=>1),'community'=>array('name'=>'Community Partner','order'=>40,'active'=>1)); }
function caes_em_sponsor_resolve_key($items,$key){ if(isset($items[$key]))return $key; foreach(array_keys($items) as $existing){if(strtolower((string)$existing)===strtolower((string)$key))return $existing;} return $key; }
function caes_em_sponsor_assignments(){ $v=get_option('caes_em_sponsor_assignments',array());return is_array($v)?$v:array(); }
function caes_em_sponsor_year(){ $y=get_option('caes_em_current_event_year','2026');return preg_match('/^20\d{2}$/D',(string)$y)?(string)$y:'2026'; }
add_action('admin_menu',function(){
 add_submenu_page('caes-event-manager','Sponsors','Sponsors','manage_options','caes-em-sponsors','caes_em_sponsors_admin');
 add_submenu_page('caes-event-manager','Sponsorship Tiers','Sponsorship Tiers','manage_options','caes-em-sponsor-tiers','caes_em_sponsor_tiers_admin');
},25);
function caes_em_sponsor_tiers_admin(){
 if(!current_user_can('manage_options'))wp_die('Insufficient permissions');$tiers=caes_em_sponsor_tiers();$message='';
 if(isset($_POST['caes_save_tier'])){check_admin_referer('caes_em_tier_save');$id=sanitize_key(wp_unslash($_POST['tier_id']??''));$name=sanitize_text_field(wp_unslash($_POST['tier_name']??''));$order=(int)($_POST['tier_order']??50);
  if(!$name)$message='Enter a tier name.';else{$id=$id?:sanitize_key($name);if(!$id)$id='tier_'.strtolower(wp_generate_password(7,false,false));$tiers[$id]=array('name'=>$name,'order'=>$order,'active'=>isset($_POST['tier_active'])?1:0);update_option('caes_em_sponsor_tiers',$tiers,false);$message='Tier saved.';}}
 if(isset($_POST['caes_delete_tier'])){check_admin_referer('caes_em_tier_delete');$id=sanitize_key(wp_unslash($_POST['tier_id']??''));$used=false;foreach(caes_em_sponsor_assignments() as $a)if(($a['tier']??'')===$id)$used=true;
  if($used)$message='Tier has sponsorship assignments. Reassign them before deleting.';elseif(isset($tiers[$id])){unset($tiers[$id]);update_option('caes_em_sponsor_tiers',$tiers,false);$message='Tier deleted.';}}
 uasort($tiers,function($a,$b){return ($a['order']??0)<=>($b['order']??0);});
 echo '<div class="wrap"><h1>Sponsorship Tiers</h1><p>Create your own tier names and display order. Existing assignments keep their tier ID when a tier is renamed. Disable a tier to hide its group without deleting its history.</p>';
 if($message)echo '<div class="notice notice-info"><p>'.esc_html($message).'</p></div>';
 $edit=sanitize_key(wp_unslash($_GET['tier']??''));$t=$tiers[$edit]??array();echo '<form method="post" style="background:#fff;padding:18px;max-width:700px">';wp_nonce_field('caes_em_tier_save');echo '<h2>'.($t?'Edit tier':'Add tier').'</h2><input type="hidden" name="tier_id" value="'.esc_attr($edit).'"><p><label>Tier name<br><input class="regular-text" name="tier_name" required value="'.esc_attr($t['name']??'').'"></label></p><p><label>Display order<br><input type="number" name="tier_order" value="'.esc_attr($t['order']??50).'"></label></p><p><label><input type="checkbox" name="tier_active" '.checked(!isset($t['active'])||$t['active'],true,false).'> Active</label></p><button class="button button-primary" name="caes_save_tier" value="1">Save tier</button></form>';
 echo '<h2>Configured tiers</h2><table class="widefat striped" style="max-width:900px"><thead><tr><th>Name</th><th>Order</th><th>Status</th><th>Actions</th></tr></thead><tbody>';
 foreach($tiers as $id=>$row){echo '<tr><td>'.esc_html($row['name']).'</td><td>'.esc_html($row['order']).'</td><td>'.(!empty($row['active'])?'Active':'Hidden').'</td><td><a class="button button-small" href="'.esc_url(add_query_arg(array('page'=>'caes-em-sponsor-tiers','tier'=>$id),admin_url('admin.php'))).'">Edit</a> <form method="post" style="display:inline">';wp_nonce_field('caes_em_tier_delete');echo '<input type="hidden" name="tier_id" value="'.esc_attr($id).'"><button class="button button-small" name="caes_delete_tier" value="1" onclick="return confirm(\'Delete this unused tier?\')">Delete</button></form></td></tr>';}
 echo '</tbody></table></div>';
}
function caes_em_sponsors_admin(){
 if(!current_user_can('manage_options'))wp_die('Insufficient permissions');$sponsors=caes_em_sponsors();$assignments=caes_em_sponsor_assignments();$tiers=caes_em_sponsor_tiers();$notice='';
 if(isset($_POST['caes_em_save_sponsor'])){check_admin_referer('caes_em_sponsor_save');$id=caes_em_sponsor_resolve_key($sponsors,sanitize_text_field(wp_unslash($_POST['sponsor_id']??'')));$name=sanitize_text_field(wp_unslash($_POST['sponsor_name']??''));$url=esc_url_raw(wp_unslash($_POST['sponsor_url']??''),array('https','http'));$logo=absint($_POST['sponsor_logo']??0);if($logo && (!wp_attachment_is_image($logo) || !current_user_can('edit_post',$logo)))$logo=0;
  if(!$name)$notice='Sponsor name is required.';elseif(!$url||!in_array(wp_parse_url($url,PHP_URL_SCHEME),array('https','http'),true))$notice='Enter a valid sponsor website URL.';else{if(!$id||!isset($sponsors[$id]))$id='sponsor_'.strtolower(wp_generate_password(10,false,false));$sponsors[$id]=array('name'=>$name,'url'=>$url,'logo'=>$logo,'tracking'=>isset($_POST['sponsor_tracking'])?1:0);update_option('caes_em_sponsors',$sponsors,false);$notice='Sponsor profile saved.';}}
 if(isset($_POST['caes_em_delete_sponsor'])){check_admin_referer('caes_em_sponsor_delete');$id=caes_em_sponsor_resolve_key($sponsors,sanitize_text_field(wp_unslash($_POST['sponsor_id']??'')));$used=false;foreach($assignments as $a)if(($a['sponsor']??'')===$id)$used=true;
  if($used)$notice='Sponsor has event assignments. Remove those first.';elseif(isset($sponsors[$id])){unset($sponsors[$id]);update_option('caes_em_sponsors',$sponsors,false);$notice='Sponsor profile deleted.';}}
 if(isset($_POST['caes_em_save_assignment'])){check_admin_referer('caes_em_assignment_save');$id=caes_em_sponsor_resolve_key($assignments,sanitize_text_field(wp_unslash($_POST['assignment_id']??'')));$sponsor=caes_em_sponsor_resolve_key($sponsors,sanitize_text_field(wp_unslash($_POST['assignment_sponsor']??'')));$tier=caes_em_sponsor_resolve_key($tiers,sanitize_text_field(wp_unslash($_POST['assignment_tier']??'')));$raw=sanitize_text_field(wp_unslash($_POST['assignment_years']??''));preg_match_all('/(?:^|[^0-9])(20[0-9]{2})(?=$|[^0-9])/',$raw,$matches);$years=array_values(array_unique($matches[1]));$override=absint($_POST['assignment_logo']??0);if($override && (!wp_attachment_is_image($override) || !current_user_can('edit_post',$override)))$override=0;
  if(!isset($sponsors[$sponsor])||!isset($tiers[$tier])||!$years)$notice='Choose a sponsor, a tier, and at least one four-digit event year.';else{if(!$id||!isset($assignments[$id]))$id='assignment_'.strtolower(wp_generate_password(10,false,false));$assignments[$id]=array('sponsor'=>$sponsor,'tier'=>$tier,'years'=>$years,'visible'=>isset($_POST['assignment_visible'])?1:0,'logo'=>$override);update_option('caes_em_sponsor_assignments',$assignments,false);$notice='Sponsorship assignment saved.';}}
 if(isset($_POST['caes_em_delete_assignment'])){check_admin_referer('caes_em_assignment_delete');$id=caes_em_sponsor_resolve_key($assignments,sanitize_text_field(wp_unslash($_POST['assignment_id']??'')));if(isset($assignments[$id])){unset($assignments[$id]);update_option('caes_em_sponsor_assignments',$assignments,false);$notice='Assignment deleted. Sponsor profile preserved.';}}
 if(isset($_POST['caes_em_save_current_year'])){check_admin_referer('caes_em_sponsor_settings');$year=sanitize_text_field(wp_unslash($_POST['current_event_year']??''));if(preg_match('/^20[0-9]{2}$/D',$year)){update_option('caes_em_current_event_year',$year,false);$notice='Current event year saved.';}else $notice='Enter a valid four-digit event year.';}
 echo '<div class="wrap"><h1>Sponsors</h1><p>Manage each organization once. Assign it to multiple event years with a tier and optional historical logo. Hidden assignments are not shown publicly.</p>';
 if($notice)echo '<div class="notice notice-info"><p>'.esc_html($notice).'</p></div>';
 echo '<form method="post" style="background:#fff;padding:16px;max-width:750px">';wp_nonce_field('caes_em_sponsor_settings');echo '<h2>Current event year</h2><p>Used for sponsor displays on regular site pages. Historical archive pages use their own event year.</p><input name="current_event_year" pattern="20[0-9]{2}" maxlength="4" value="'.esc_attr(caes_em_sponsor_year()).'"> <button class="button button-primary" name="caes_em_save_current_year" value="1">Save current year</button></form>';
 $edit=caes_em_sponsor_resolve_key($sponsors,sanitize_text_field(wp_unslash($_GET['sponsor']??'')));$current=$sponsors[$edit]??array();echo '<form method="post" style="background:#fff;padding:18px;max-width:850px;margin-top:18px">';wp_nonce_field('caes_em_sponsor_save');echo '<h2>'.($current?'Edit sponsor':'Add sponsor').'</h2><input type="hidden" name="sponsor_id" value="'.esc_attr($current?$edit:'').'"><p><label><strong>Sponsor name</strong><br><input class="regular-text" name="sponsor_name" required value="'.esc_attr($current['name']??'').'"></label></p><p><label><strong>Website URL</strong><br><input class="large-text" type="url" name="sponsor_url" required placeholder="https://example.com" value="'.esc_attr($current['url']??'').'"></label></p><p><label><strong>Logo (Media Library)</strong><br><input type="hidden" class="caes-sponsor-logo-id" name="sponsor_logo" value="'.esc_attr($current['logo']??0).'"><button type="button" class="button caes-sponsor-choose">Choose logo</button> <span class="caes-sponsor-logo-label">'.esc_html(!empty($current['logo'])?basename((string)get_attached_file((int)$current['logo'])):'No logo selected').'</span></label></p><p><label><input type="checkbox" name="sponsor_tracking" '.checked(!isset($current['tracking'])||$current['tracking'],true,false).'> Add UTM tracking to sponsor links</label></p><button class="button button-primary" name="caes_em_save_sponsor" value="1">Save sponsor</button> <a class="button" href="'.esc_url(admin_url('admin.php?page=caes-em-sponsors')).'">Clear form</a></form>';
 echo '<h2>Sponsor directory</h2><table class="widefat striped" style="max-width:1050px"><thead><tr><th>Organization</th><th>Website</th><th>Logo</th><th>Actions</th></tr></thead><tbody>';
 foreach($sponsors as $id=>$s){echo '<tr><td>'.esc_html($s['name']).'</td><td>'.esc_html($s['url']).'</td><td>'.(!empty($s['logo'])?wp_get_attachment_image((int)$s['logo'],array(90,50)):'Not set').'</td><td><a class="button button-small" href="'.esc_url(add_query_arg(array('page'=>'caes-em-sponsors','sponsor'=>$id),admin_url('admin.php'))).'">Edit</a> <form method="post" style="display:inline">';wp_nonce_field('caes_em_sponsor_delete');echo '<input type="hidden" name="sponsor_id" value="'.esc_attr($id).'"><button class="button button-small" name="caes_em_delete_sponsor" value="1" onclick="return confirm(\'Delete this sponsor profile? Linked assignments block deletion.\')">Delete</button></form></td></tr>';}
 echo '</tbody></table>';
 $ae=caes_em_sponsor_resolve_key($assignments,sanitize_text_field(wp_unslash($_GET['assignment']??'')));$a=$assignments[$ae]??array();echo '<form method="post" style="background:#fff;padding:18px;max-width:850px;margin-top:24px">';wp_nonce_field('caes_em_assignment_save');echo '<h2>'.($a?'Edit sponsorship assignment':'Add sponsorship assignment').'</h2><input type="hidden" name="assignment_id" value="'.esc_attr($a?$ae:'').'"><p><label>Sponsor<br><select name="assignment_sponsor" required><option value="">Select sponsor</option>';foreach($sponsors as $id=>$s)echo '<option value="'.esc_attr($id).'" '.selected($a['sponsor']??'',$id,false).'>'.esc_html($s['name']).'</option>';echo '</select></label></p><p><label>Tier<br><select name="assignment_tier" required><option value="">Select tier</option>';foreach($tiers as $id=>$t)echo '<option value="'.esc_attr($id).'" '.selected($a['tier']??'',$id,false).'>'.esc_html($t['name']).'</option>';echo '</select></label> <a href="'.esc_url(admin_url('admin.php?page=caes-em-sponsor-tiers')).'">Manage tiers</a></p><p><label>Event years (comma-separated, e.g. 2026, 2027, 2028)<br><input class="regular-text" name="assignment_years" required value="'.esc_attr(implode(', ',$a['years']??array())).'"></label></p><p><label>Historical logo override (optional)<br><input type="hidden" class="caes-sponsor-logo-id" name="assignment_logo" value="'.esc_attr($a['logo']??0).'"><button type="button" class="button caes-sponsor-choose">Choose override logo</button> <span class="caes-sponsor-logo-label">'.esc_html(!empty($a['logo'])?'Logo selected':'Use current sponsor logo').'</span></label></p><p><label><input type="checkbox" name="assignment_visible" '.checked(!isset($a['visible'])||$a['visible'],true,false).'> Publicly visible for selected years</label></p><button class="button button-primary" name="caes_em_save_assignment" value="1">Save assignment</button> <a class="button" href="'.esc_url(admin_url('admin.php?page=caes-em-sponsors')).'">Clear form</a></form>';
 echo '<h2>Year assignments</h2><table class="widefat striped" style="max-width:1050px"><thead><tr><th>Sponsor</th><th>Years</th><th>Tier</th><th>Visible</th><th>Actions</th></tr></thead><tbody>';
 foreach($assignments as $id=>$row){echo '<tr><td>'.esc_html($sponsors[$row['sponsor']]['name']??'Missing sponsor').'</td><td>'.esc_html(implode(', ',$row['years']??array())).'</td><td>'.esc_html($tiers[$row['tier']]['name']??'Missing tier').'</td><td>'.(!empty($row['visible'])?'Yes':'No').'</td><td><a class="button button-small" href="'.esc_url(add_query_arg(array('page'=>'caes-em-sponsors','assignment'=>$id),admin_url('admin.php'))).'">Edit</a> <form method="post" style="display:inline">';wp_nonce_field('caes_em_assignment_delete');echo '<input type="hidden" name="assignment_id" value="'.esc_attr($id).'"><button class="button button-small" name="caes_em_delete_assignment" value="1" onclick="return confirm(\'Delete this sponsorship assignment? The sponsor profile will remain.\')">Delete</button></form></td></tr>';}
 echo '</tbody></table>';if(function_exists('caes_em_shortcode_panel'))caes_em_shortcode_panel('Sponsor display','[event_sponsors]');echo '</div>';
}
add_action('admin_enqueue_scripts',function($hook){
 if(strpos((string)$hook,'caes-em-sponsors')===false)return;
 wp_enqueue_media();wp_register_script('caes-em-sponsor-admin',false,array('jquery'),'0.1.13',true);wp_enqueue_script('caes-em-sponsor-admin');
 $js=<<<'JS'
jQuery(function($){$(document).on('click','.caes-sponsor-choose',function(e){e.preventDefault();var btn=$(this),field=btn.closest('label').find('.caes-sponsor-logo-id'),label=btn.closest('label').find('.caes-sponsor-logo-label');var frame=wp.media({title:'Choose sponsor logo',button:{text:'Use logo'},multiple:false,library:{type:'image'}});frame.on('select',function(){var item=frame.state().get('selection').first().toJSON();field.val(item.id);label.text(item.filename);});frame.open();});});
JS;
 wp_add_inline_script('caes-em-sponsor-admin',$js);
});
function caes_em_sponsor_link($url,$year,$tier,$tracking){if(!$tracking)return $url;$parts=array('utm_source'=>'ca_email_summit_'.$year,'utm_medium'=>'referral','utm_campaign'=>'sponsor','utm_content'=>$tier);return add_query_arg($parts,$url);}
add_shortcode('event_sponsors',function($atts){$atts=shortcode_atts(array('year'=>''),$atts,'event_sponsors');$year=trim((string)$atts['year']);if(!$year){$page=get_queried_object();if($page instanceof WP_Post && preg_match('/^summit-(20\d{2})$/D',$page->post_name,$m))$year=$m[1];else $year=caes_em_sponsor_year();}if(!preg_match('/^20\d{2}$/D',$year))return '';
 $sponsors=caes_em_sponsors();$tiers=caes_em_sponsor_tiers();$groups=array();foreach(caes_em_sponsor_assignments() as $a){if(empty($a['visible'])||!in_array($year,$a['years']??array(),true))continue;$sid=$a['sponsor']??'';$tid=$a['tier']??'';if(!isset($sponsors[$sid],$tiers[$tid])||empty($tiers[$tid]['active']))continue;$groups[$tid][]=$a;}
 if(!$groups)return '';uasort($tiers,function($a,$b){return ($a['order']??0)<=>($b['order']??0);});$out='<section class="caes-section caes-sponsors caes-managed-sponsors" aria-label="Event sponsors"><div class="caes-managed-sponsors-inner"><p class="caes-eyebrow">OUR SPONSORS</p><h2>Supported by the email community</h2>';
 foreach($tiers as $tid=>$tier){if(empty($groups[$tid]))continue;usort($groups[$tid],function($a,$b)use($sponsors){$nameA=$sponsors[$a['sponsor']]['name']??'';$nameB=$sponsors[$b['sponsor']]['name']??'';return strnatcasecmp($nameA,$nameB);});$out.='<div class="caes-managed-sponsor-tier"><h3 class="caes-tier-label">'.esc_html($tier['name']).'</h3><div class="caes-managed-sponsor-logos">';$seen=array();foreach($groups[$tid] as $a){$s=$sponsors[$a['sponsor']];if(isset($seen[$a['sponsor']]))continue;$seen[$a['sponsor']]=1;$logo=(int)(!empty($a['logo'])?$a['logo']:($s['logo']??0));$img=$logo?wp_get_attachment_image($logo,'medium',false,array('loading'=>'lazy','alt'=>$s['name'].' logo')):'';$link=caes_em_sponsor_link($s['url'],$year,$tid,!empty($s['tracking']));$out.='<a class="caes-logo-tile caes-managed-sponsor" href="'.esc_url($link).'" target="_blank" rel="noopener noreferrer sponsored" aria-label="Visit '.esc_attr($s['name']).'"><span>'.($img?:esc_html($s['name'])).'</span></a>';}$out.='</div></div>';}
 return $out.'</div></section>';});
